  content = $json${"level_id":"1.5","badge_name":"সুরক্ষা কবচ","level_title":"ডিসচার্জ রড ব্যবহারের কায়দা","mission_briefing":"কন্ট্রোল রুম থেকে আপনাকে 'পারমিট-টু-ওয়ার্ক' দেওয়া হয়েছে। লাইন বন্ধ। কিন্তু একটি ঘুমন্ত বাঘও বাঘই থাকে। তেমনি, একটি ডেড (dead) লাইনও অদৃশ্য বিপদ ধরে রাখতে পারে। এই লেভেলের মিশন হলো, বিদ্যুতের এই লুকানো শক্তিকে চেনা এবং ডিসচার্জ রড দিয়ে লাইনকে প্রকৃত অর্থে নিরাপদ করা। এটি আপনার চূড়ান্ত নিরাপত্তা নিশ্চিতকারী।","sections":[{"title":"কেন একটি ডেড (dead) লাইনও বিপজ্জনক হতে পারে?","points":[{"item_name":"১. অদৃশ্য শত্রু: ক্যাপাসিটিভ চার্জ এবং ইন্ডুসড ভোল্টেজ","image_name":"/images/loader/parts_of_discharge_rod.webp","image_caption":"ডিসচার্জ রড ও তার অংশসমূহ","specifications":"লাইন বন্ধ করার পরেও দুটি প্রধান কারণে এতে বিপজ্জনক ভোল্টেজ থাকতে পারে:\n• ক্যাপাসিটিভ চার্জ (Capacitive Charge): ওভারহেড লাইন এবং মাটির মধ্যবর্তী বাতাস একটি ইনসুলেটর হিসেবে কাজ করে, যা একটি বিশাল প্রাকৃতিক ক্যাপাসিটর তৈরি করে। এই ক্যাপাসিটর বিপজ্জনক বৈদ্যুতিক চার্জ ধরে রাখতে পারে।\n• ইন্ডুসড ভোল্টেজ (Induced Voltage): যদি আপনার ডেড (dead) লাইনটি অন্য কোনো হাই-ভোল্টেজ লাইভ (live) লাইনের পাশ দিয়ে যায়, তবে চালু লাইনটির চৌম্বক ক্ষেত্র বন্ধ লাইনটিতে নতুন করে ভোল্টেজ তৈরি করতে পারে।","importance":"এই দুটি কারণে জমে থাকা চার্জ একজন মানুষকে মারাত্মক শক দেওয়ার জন্য যথেষ্ট। পারমিট নেওয়া একটি প্রক্রিয়া মাত্র, কিন্তু ডিসচার্জ করা হলো শারীরিক সুরক্ষা নিশ্চিত করা। [[/images/loader/extra_precaution_during_rain.webp|inline|ভেজা পরিবেশে বাড়তি সতর্কতা — ভেজা রড বা ইনসুলেটর বিপজ্জনক]]","daily_check":"কাজে যাওয়ার আগে নিশ্চিত করুন আপনার কাছে সঠিক ভোল্টেজ রেটিং-এর ডিসচার্জ রড আছে। একটি ১১ কেভি রড ৩৩ কেভি লাইনে ব্যবহার করা আত্মহত্যার সামিল। ভেজা বা ঝড়ো আবহাওয়ায় কাজ স্থগিত করুন।"},{"item_name":"২. জীবনরক্ষাকারী পদ্ধতি: আগে মাটি, পরে লাইন","image_name":"/images/loader/wrong_vs_right_discharge_rod.webp","image_caption":"ভুল বনাম সঠিক — আগে আর্থিং, পরে লাইন","specifications":"ডিসচার্জ রড ব্যবহারের একটিই সঠিক নিয়ম, যার কোনো ব্যতিক্রম নেই:\n• ধাপ ১ (সবচেয়ে জরুরি): রডের আর্থিং ক্ল্যাম্পটি প্রথমে একটি নির্ভরযোগ্য আর্থিং পয়েন্টে (যেমন আর্থ রড, পোলের আর্থিং স্ট্রিপ) খুব ভালোভাবে সংযুক্ত করুন।\n• ধাপ ২: আর্থিং নিশ্চিত করার পর, রডের হুক অংশটি দিয়ে লাইনের তিনটি কন্ডাক্টরকে (R, Y, B) একে একে স্পর্শ করান। একটি ছোট স্পার্ক বা 'চট্' শব্দ হতে পারে, যা প্রমাণ করে যে আপনি একটি সম্ভাব্য বিপদকে নিষ্ক্রিয় করেছেন।","importance":"এই ক্রমটি যদি উল্টে যায় (অর্থাৎ আগে লাইনে স্পর্শ করে পরে আর্থিং), তাহলে জমে থাকা চার্জ আপনার শরীরের মধ্যে দিয়ে মাটিতে যাওয়ার চেষ্টা করবে, যা মুহূর্তের মধ্যে মৃত্যু ঘটাতে পারে। এই নিয়মটি জীবন ও মৃত্যুর মধ্যে পার্থক্য গড়ে দেয়।","daily_check":"প্রতিবার ব্যবহারের আগে আপনার আর্থিং পয়েন্টটি পরীক্ষা করুন। মরিচা ধরা বা আলগা কানেকশনে আর্থিং ঠিকমতো কাজ করে না।"},{"item_name":"৩. আপনার অস্ত্রের স্বাস্থ্য পরীক্ষা","image_name":"/images/loader/daily_check_discharge_rod.webp","image_caption":"রড ব্যবহারের আগে ৩০ সেকেন্ড চেক","specifications":"প্রতিবার ব্যবহারের আগে আপনার ডিসচার্জ রডটি পরীক্ষা করুন:\n• ইনসুলেটিং স্টিক: দেখুন এটি পরিষ্কার, শুকনো এবং ফাটলমুক্ত আছে কিনা।\n• কপার কেবিল: কেবিলের ইনসুলেশন কাটা বা ছেঁড়া আছে কিনা এবং দুই প্রান্তের কানেকশন মজবুত আছে কিনা, তা পরীক্ষা করুন।\n• ক্ল্যাম্প ও হুক: নিশ্চিত করুন এগুলো পরিষ্কার এবং এদের গ্রিপ মজবুত আছে।","importance":"একটি ময়লা বা ভাঙা ডিসচার্জ রড নিজেই বিদ্যুৎ পরিবাহী হয়ে উঠতে পারে, যা আপনার সুরক্ষা কবচকে মারণাস্ত্রে পরিণত করবে।","daily_check":"এই দ্রুত পরীক্ষাটি আপনার কাজের রুটিনের একটি বাধ্যতামূলক অংশ হওয়া উচিত।"},{"item_name":"৪. কোন লাইনে কোন রড — ভোল্টেজ রেটিং","specifications":"ডিসচার্জ রড লাইনের ভোল্টেজ অনুযায়ী বাছাই করতে হয়। রডের বডিতে বা লেবেলে রেটিং দেখা থাকে—সেটাই মানুন।\n• এলটি / ৪৪০ ভি: সংশ্লিষ্ট এলটি ডিসচার্জ/আর্থিং সেট\n• ১১ কেভি: ১১ কেভি রেটেড ডিসচার্জ রড\n• ৩৩ কেভি: ৩৩ কেভি রেটেড ডিসচার্জ রড\n• এর ওপরে: সেই ভোল্টেজের জন্য নির্ধারিত রড—নিচু রেটিংয়ের রড কখনোই ব্যবহার করবেন না।","importance":"১১ কেভির রড নিয়ে ৩৩ কেভির কাজে যাওয়া মানে ইনসুলেশন ভেঙে যাওয়ার ঝুঁকি। লাইন ডেড (dead) বলে ধরে নিয়েও ভুল রেটিংয়ের রড জীবন নিতে পারে।","daily_check":"কাজের অর্ডার দেখে লাইনের ভোল্টেজ মিলিয়ে নিন, তারপর রডের লেবেল চেক করুন। মিল না থাকলে কাজ শুরু করবেন না—স্টোর বা সুপারভাইজারকে বলুন।"},{"item_name":"৫. পিভিসি জুগাড় নয় — স্ট্যান্ডার্ড ডিসচার্জ রডই চাই","image_name":"/images/loader/discharge_jugaad_vs_standard.webp","image_caption":"জুগাড় ✗ · স্ট্যান্ডার্ড ডিসচার্জ রড ✓","specifications":"মাঠে দেখা যায়—হার্ড পিভিসি ওয়াটার পাইপ কেটে ওপরে মেটাল হুক, নিচে নমনীয় তার দিয়ে আর্থ। চেহারায় রড মনে হলেও এটা সার্টিফায়েড ডিসচার্জ রড বা হট স্টিক নয়।\nস্ট্যান্ডার্ড রডে থাকে: পরীক্ষিত ইনসুলেটিং স্টিক (সাধারণত ফাইবারগ্লাস), মজবুত হুক, পর্যাপ্ত ক্রস-সেকশনের কপার কেবিল, আর নির্ভরযোগ্য আর্থ ক্ল্যাম্প—সবই ভোল্টেজ রেটিংসহ।","importance":"আসল বিপদে জুগাড় কাজ করে না। পিভিসি ফাটতে পারে, ভেজা-ময়লায় লিক হতে পারে; হুক মেটাল—লাইভ (live) বা চার্জযুক্ত লাইনের কাছে এটা নিয়ে ঢোকা নিজেকে বিপদে ফেলা। প্লাস্টিক দেখে নিরাপদ ভাবা ভুল।","daily_check":"হাতে যা আছে তা কি স্টোর-ইস্যু স্ট্যান্ডার্ড রড? জুগাড় দেখলে ব্যবহার বন্ধ করুন; সঠিক রড না পেলে কাজ স্থগিত রাখুন।"}]}],"pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. কন্ট্রোল রুমকে বিশ্বাস করুন, কিন্তু ভেরিফাই করুন: পারমিট নিন, কিন্তু লাইনকে ততক্ষণ পর্যন্ত লাইভ (live) মনে করুন যতক্ষণ না আপনি নিজের হাতে তিনটি ফেজ ডিসচার্জ করছেন।","২. স্পার্ক আপনার বন্ধু: ডিসচার্জ করার সময় যে ছোট স্পার্ক হয়, তাকে ভয় পাবেন না। ওটা প্রমাণ করে যে আপনি একটি লুকানো বিপদকে এড়াতে পেরেছেন।","৩. কাজ শেষ না হওয়া পর্যন্ত আর্থিং রাখুন: [[/images/loader/keep_earthing_till+work_completed.webp|inline|অস্থায়ী আর্থিং — কাজ শেষ না হওয়া পর্যন্ত]] অনেক ক্ষেত্রে, যতক্ষণ লাইনে কাজ চলে, ততক্ষণ সেটিকে আর্থিং করে রাখাই নিয়ম, যাতে ভুলবশত লাইন চালু হলেও বিপদ এড়ানো যায়।","৪. জুগাড়ে ভরসা নয়: পিভিসি পাইপের হোমমেড রড দেখলেই থামুন। স্ট্যান্ডার্ড রড আর সঠিক ভোল্টেজ রেটিং—এ দুটো ছাড়া ডিসচার্জ শুরু করবেন না।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","image_name":"/images/loader/wrong_vs_right_discharge_rod.webp","image_caption":"ভুল বনাম সঠিক ডিসচার্জ পদ্ধতি","myths":[{"myth":"লাইন তো মাত্র ৫ মিনিটের জন্য বন্ধ করা হয়েছে, এর মধ্যে আর কী চার্জ জমবে? ডিসচার্জ করার দরকার নেই।","reality":"ভুল। ক্যাপাসিটিভ চার্জ এবং ইন্ডুসড ভোল্টেজ মুহূর্তের মধ্যে তৈরি হতে পারে। সময় যতই কম হোক না কেন, ডিসচার্জ করা বাধ্যতামূলক।"},{"myth":"আগে তারে লাগিয়ে পরে আর্থিং করলে তাড়াতাড়ি কাজ হয় এবং স্পার্কটাও ভালো দেখা যায়।","reality":"এটি একটি মারাত্মক এবং মূর্খ ধারণা। এই পদ্ধতিতে আপনি নিজেকে এবং আর্থিং পয়েন্টের মধ্যে একটি সেতু তৈরি করেন, যার ফল হতে পারে মৃত্যু।"},{"myth":"পিভিসি পাইপ তো প্লাস্টিক—এটা দিয়েই ডিসচার্জ রডের কাজ চলবে।","reality":"[[/images/loader/discharge_jugaad_vs_standard.webp|inline|জুগাড় নয় — স্ট্যান্ডার্ড ডিসচার্জ রড]] না ভাই। প্লাস্টিক দেখে নিরাপদ ভাবা ভুল। আসল বিপদে জুগাড় বাঁচায় না। চাই পরীক্ষিত ইনসুলেটিং স্টিক, সঠিক কেবিল আর ক্ল্যাম্প—রেটিং মিলিয়ে।"}]},"advanced_section":{"title":"এর পেছনের ইঞ্জিনিয়ারিং ফ্যাক্টস","facts":[{"title":"ক্যাপাসিট্যান্স এবং ফ্যারাড (Capacitance and Farads)","content":"ক্যাপাসিট্যান্স হলো কোনো সিস্টেমের চার্জ ধরে রাখার ক্ষমতা, যার একক ফ্যারাড। একটি ওভারহেড লাইন এবং পৃথিবী সমান্তরাল প্লেট ক্যাপাসিটরের মতো কাজ করে। লাইনের দৈর্ঘ্য এবং উচ্চতা যত বেশি হয়, তার চার্জ ধরে রাখার ক্ষমতাও তত বাড়ে।"},{"title":"ইলেক্ট্রোম্যাগনেটিক ইন্ডাকশন (Electromagnetic Induction)","content":"এটি মাইকেল ফ্যারাডের আবিষ্কৃত একটি সূত্র, যার ওপর ভিত্তি করে ট্রান্সফরমার এবং মোটর কাজ করে। যখন একটি লাইভ (live) এসি লাইনের কারেন্ট ক্রমাগত দিক পরিবর্তন করে, তখন তার চারপাশে একটি পরিবর্তনশীল চৌম্বক ক্ষেত্র তৈরি হয়। এই চৌম্বক ক্ষেত্রটি পাশের যেকোনো পরিবাহীতে (যেমন আপনার ডেড (dead) লাইন) একটি নতুন ভোল্টেজ তৈরি বা 'ইন্ডিউস' করে।"}]}}$json$::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '1.5' AND language = 'bn';
